{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'

class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)
const newTable = () => ({ t: 'table', m: new Map(), closed: false })

class Parser {
  constructor() {
    this.root = newTable()
    this.cur = this.root
    this.curPath = []
  }

  line(text) {
    this.s = text
    this.i = 0
    this.ws()
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';') return
    if (c === '[') return this.header()
    const path = this.dotted()
    this.ws()
    if (this.s[this.i] !== '=') fail('expected key = value')
    this.i++
    const v = this.value([...this.curPath, ...path])
    this.assign(this.cur, this.curPath, path, v)
    this.rest('trailing text after a value')
  }

  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  rest(msg) {
    this.ws()
    if (!this.atEnd()) fail(msg)
  }

  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (isNameChar(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const out = []
    this.ws()
    out.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        out.push(this.name())
      } else { this.i = save; break }
    }
    return out
  }

  basic() {
    this.i++
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      this.i++
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        this.i += 4
        out += String.fromCharCode(parseInt(h, 16))
      } else fail('invalid escape \\' + e)
    }
  }

  literal() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return r
  }

  value(path) {
    this.ws()
    const c = this.s[this.i]
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]}'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    const m = new RegExp(`^[+-]?${D}(\\.${D})?([eE][+-]?${D})?$`).test(w)
    if (m) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail('invalid value ' + w)
  }

  array(path) {
    this.i++
    const items = []
    this.ws()
    if (this.s[this.i] === ']') { this.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      items.push(this.value([...path, `[${items.length}]`]))
      this.ws()
      const c = this.s[this.i]
      if (c === ']') { this.i++; break }
      if (c !== ',') fail('unterminated array')
      this.i++
      this.ws()
      if (this.s[this.i] === ']') { this.i++; break }
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    tbl.closed = true
    this.ws()
    if (this.s[this.i] === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const k = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...path, ...k])
      this.assign(tbl, path, k, v)
      this.ws()
      const c = this.s[this.i]
      if (c === '}') { this.i++; return tbl }
      if (c !== ',') fail('unterminated inline table')
      this.i++
    }
  }

  // Descend one name for a dotted walk; creates an implicit table when absent.
  step(tbl, key, path) {
    let n = tbl.m.get(key)
    if (!n) { n = newTable(); tbl.m.set(key, n) }
    if (n.t === 'table') return n
    if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
    return fail(`${path.join('.')} is not a table`)
  }

  assign(base, basePath, keys, v) {
    let t = base
    const p = [...basePath]
    for (let k = 0; k < keys.length - 1; k++) {
      p.push(keys[k])
      t = this.step(t, keys[k], p)
    }
    const last = keys[keys.length - 1]
    p.push(last)
    if (t.m.has(last)) fail(`key ${p.join('.')} is defined twice`)
    t.m.set(last, v)
  }

  header() {
    this.i++
    const aot = this.s[this.i] === '['
    if (aot) this.i++
    const path = this.dotted()
    this.ws()
    if (this.s[this.i] !== ']') fail('unterminated table header')
    this.i++
    if (aot) {
      if (this.s[this.i] !== ']') fail('unterminated table header')
      this.i++
    }
    this.rest('trailing text after a table header')
    let t = this.root
    const p = []
    for (let k = 0; k < path.length - 1; k++) {
      p.push(path[k])
      t = this.step(t, path[k], p)
    }
    const last = path[path.length - 1]
    p.push(last)
    const n = t.m.get(last)
    const full = p.join('.')
    if (aot) {
      let arr = n
      if (!arr) { arr = { t: 'array', items: [], aot: true }; t.m.set(last, arr) }
      else if (arr.t !== 'array' || !arr.aot) fail(`${full} is not an array of tables`)
      const el = newTable()
      el.closed = true
      arr.items.push(el)
      this.cur = el
    } else if (!n) {
      const el = newTable()
      el.closed = true
      t.m.set(last, el)
      this.cur = el
    } else if (n.t !== 'table') fail(`${full} is not a table`)
    else {
      if (n.closed) fail(`table ${full} is defined twice`)
      n.closed = true
      this.cur = n
    }
    this.curPath = p
  }
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedEntries = (t) => [...t.m.entries()].sort((a, b) => cmp(a[0], b[0]))

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const es = sortedEntries(n)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${toJson(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function toKeys(n, path, out) {
  const kids = n.t === 'table' ? sortedEntries(n).map(([k, v]) => [(path ? path + '.' : '') + k, v])
    : n.t === 'array' ? n.items.map((v, i) => [`${path}[${i}]`, v]) : []
  for (const [p, v] of kids) {
    out.push(`${p} ${v.t}`)
    toKeys(v, p, out)
  }
  return out
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const parser = new Parser()
let lineNo = 0
try {
  for (const l of lines) { lineNo++; parser.line(l) }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${lineNo}: ${e.message}\n`)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(parser.root, 0) + '\n')
else {
  const out = toKeys(parser.root, '', [])
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}
