      items.push(this.value([...path, `[${items.length}]`]))
      this.ws()
      const c = this.s[this.i]
      if (c === ']') { this.i++; break }
      if (c !== ',') fail('unterminated array')
      this.i++
      this.ws()
      if (this.s[this.i] === ']') { this.i++; break }
    }
    return { t: 'array', items, aot: false }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    tbl.closed = true
    this.ws()
    if (this.s[this.i] === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const k = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value([...path, ...k])
      this.assign(tbl, path, k, v)
      this.ws()
      const c = this.s[this.i]
      if (c === '}') { this.i++; return tbl }
      if (c !== ',') fail('unterminated inline table')
      this.i++
    }
  }

  // Descend one name for a dotted walk; creates an implicit table when absent.
  step(tbl, key, path) {
    let n = tbl.m.get(key)
    if (!n) { n = newTable(); tbl.m.set(key, n) }
    if (n.t === 'table') return n
    if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
    return fail(`${path.join('.')} is not a table`)
  }

  assign(base, basePath, keys, v) {
    let t = base
    const p = [...basePath]
    for (let k = 0; k < keys.length - 1; k++) {
      p.push(keys[k])
      t = this.step(t, keys[k], p)
    }
    const last = keys[keys.length - 1]
    p.push(last)
    if (t.m.has(last)) fail(`key ${p.join('.')} is defined twice`)
    t.m.set(last, v)
  }

  header() {
    this.i++
    const aot = this.s[this.i] === '['
    if (aot) this.i++
    const path = this.dotted()
    this.ws()
    if (this.s[this.i] !== ']') fail('unterminated table header')
    this.i++
    if (aot) {
      if (this.s[this.i] !== ']') fail('unterminated table header')
      this.i++
    }
    this.rest('trailing text after a table header')
    let t = this.root
    const p = []
    for (let k = 0; k < path.length - 1; k++) {
      p.push(path[k])
      t = this.step(t, path[k], p)
    }
    const last = path[path.length - 1]
    p.push(last)
    const n = t.m.get(last)
    const full = p.join('.')
    if (aot) {
      let arr = n
      if (!arr) { arr = { t: 'array', items: [], aot: true }; t.m.set(last, arr) }
      else if (arr.t !== 'array' || !arr.aot) fail(`${full} is not an array of tables`)
      const el = newTable()
      el.closed = true
      arr.items.push(el)
      this.cur = el
    } else if (!n) {
      const el = newTable()
      el.closed = true
      t.m.set(last, el)
      this.cur = el
    } else if (n.t !== 'table') fail(`${full} is not a table`)
    else {
      if (n.closed) fail(`table ${full} is defined twice`)
      n.closed = true
      this.cur = n
    }
    this.curPath = p
  }
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedEntries = (t) => [...t.m.entries()].sort((a, b) => cmp(a[0], b[0]))

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const es = sortedEntries(n)
    if (!es.length) return '{}'
    return '{\n' + es.map(([k, v]) => `${pad}${JSON.stringify(k)}: ${toJson(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function toKeys(n, path, out) {
  const kids = n.t === 'table' ? sortedEntries(n).map(([k, v]) => [(path ? path + '.' : '') + k, v])
    : n.t === 'array' ? n.items.map((v, i) => [`${path}[${i}]`, v]) : []
  for (const [p, v] of kids) {
    out.push(`${p} ${v.t}`)
    toKeys(v, p, out)
  }
  return out
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const parser = new Parser()
let lineNo = 0
try {
  for (const l of lines) { lineNo++; parser.line(l) }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: line ${lineNo}: ${e.message}\n`)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(parser.root, 0) + '\n')
else {
  const out = toKeys(parser.root, '', [])
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}
