{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(source) {
  const cs = Array.from(source)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  function adv() {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }

  // consume digits of a run; underscore only between two digits of the run
  function run(isD) {
    let any = false
    while (i < n) {
      if (isD(cs[i])) {
