const byName = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    for (const [c, v] of votes) history.get(c).push(v)
    const list = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : byName(a[0], b[0])))
    const round = { list, exhausted: total - active }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = list[0]
    if (top[1] * 2n > active) return { rounds, winner: top[0] }
    let tied = [...continuing]
    const min = list[list.length - 1][1]
    tied = tied.filter((c) => votes.get(c) === min)
    for (let r = 0; tied.length > 1 && r < rounds.length; r++) {
      const m = tied.reduce((x, c) => (history.get(c)[r] < x ? history.get(c)[r] : x), history.get(tied[0])[r])
      tied = tied.filter((c) => history.get(c)[r] === m)
    }
    // Restart from the first round is equivalent: one pass keeps only the minimum at each round.
    const out = tied.sort(byName)[tied.length - 1]
    round.eliminated = out
    continuing.delete(out)
  }
}
