      const c = group[0]
      const lines = (c.who === 0 ? mine : theirs).slice(c.ss, c.se)
      regions.push({ type: c.who === 0 ? 'mine' : 'theirs', lines })
      continue
    }
    const repl = who => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseLines
      const s = Math.min(...g.map(c => c.bs)), e = Math.max(...g.map(c => c.be))
