import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const word = t[0]
      if (word === 'bucket' || word === 'window') {
        const n = word === 'bucket' ? 5 : 4
        if (t.length !== n) {
          throw new Fail(word === 'bucket'
            ? 'expected bucket <name> <capacity> <refill> <per>'
            : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (word === 'bucket') {
          p = { kind: 'bucket', name: t[1], capacity: int('capacity', t[2], 1), refill: int('refill', t[3], 0), per: int('per', t[4], 1) }
        } else {
          p = { kind: 'window', name: t[1], limit: int('limit', t[2], 0), span: int('span', t[3], 1) }
        }
        if (events.length) throw new Fail('declarations must come before the first event')
        if (policies.has(p.name)) throw new Fail(`policy ${p.name} is declared twice`)
        policies.set(p.name, p)
      } else if (word === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (events.length) throw new Fail('declarations must come before the first event')
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        const list = []
        for (const name of t.slice(2)) {
          if (!policies.has(name)) throw new Fail(`unknown policy ${name}`)
          list.push(policies.get(name))
        }
        routes.set(t[1], list)
      } else if (word === 'event') {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
      } else {
        throw new Fail(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${i + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
  return { routes, events }
}

const { routes, events } = parse(readFileSync(0, 'utf8'))
const prefixes = [...routes.keys()]
const states = new Map()

function stateFor(policy, key, tick) {
  const id = policy.name + '\0' + key
  let s = states.get(id)
  if (!s) {
    s = policy.kind === 'bucket'
      ? { scaled: policy.capacity * policy.per, last: tick }
      : { ticks: [] }
    states.set(id, s)
  }
  return s
}

function advance(policy, s, tick) {
  if (policy.kind === 'bucket') {
    const cap = policy.capacity * policy.per
    s.scaled += policy.refill * (tick - s.last)
    if (s.scaled > cap) s.scaled = cap
    s.last = tick
  } else {
    const cut = tick - policy.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}

const allows = (policy, s) =>
  policy.kind === 'bucket' ? s.scaled >= policy.per : BigInt(s.ticks.length) < policy.limit

const out = []
const counts = new Map()
let ta = 0
let td = 0
for (const { tick, key } of events) {
  let best = null
  for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
  let denier = null
  if (best !== null) {
    const list = routes.get(best)
    const ss = list.map((p) => {
      const s = stateFor(p, key, tick)
      advance(p, s, tick)
      return s
    })
    for (let i = 0; i < list.length; i++) {
      if (!allows(list[i], ss[i])) { denier = list[i].name; break }
    }
    if (denier === null) {
      list.forEach((p, i) => {
        if (p.kind === 'bucket') ss[i].scaled -= p.per
        else ss[i].ticks.push(tick)
      })
    }
  }
  const c = counts.get(key) ?? { a: 0, d: 0 }
  counts.set(key, c)
  if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
  out.push(`${tick} ${key} ${denier === null ? 'allow' : 'deny ' + denier}`)
}
if (mode === 'summary') {
  const o = [...counts.keys()].sort().map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
  o.push(`total allowed=${ta} denied=${td}`)
  process.stdout.write(o.join('\n') + '\n')
} else if (out.length) {
  process.stdout.write(out.join('\n') + '\n')
}
