import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (cands !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = [...seen]
  } else if (word === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!COUNT.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: Number(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
}
if (cands === null) fail('error: no candidates')

const continuing = new Set(cands)
const history = [] // Map per round
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  let total = 0
  for (const b of ballots) {
    total += b.count
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  history.push(counts)
  const listed = [...counts.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let text = `round ${roundNo}: ` + listed.map(([k, v]) => `${k}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(text)
  if (active === 0) break
  const top = listed.find(([, v]) => v * 2 > active)
  if (top) { winner = top[0]; break }
  let s = [...continuing]
  const first = Math.min(...s.map((c) => counts.get(c)))
  s = s.filter((c) => counts.get(c) === first)
  for (let r = 0; r < history.length && s.length > 1; r++) {
    const vals = s.map((c) => history[r].get(c))
    const m = Math.min(...vals)
    if (vals.some((v) => v !== m)) s = s.filter((c) => history[r].get(c) === m)
  }
  s.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  const elim = s[s.length - 1]
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner !== null ? `winner ${winner}` : 'no winner'
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${roundNo}\n${end}\n`)
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write CLI and run tests"}

