{"command":"cat > src/uri.js <<'EOF'
export class UriError extends Error {}

export function parse(s) {
  const r = { scheme: null, auth: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    r.auth = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function splitAuth(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const c = a.indexOf(':', rb < 0 ? 0 : rb)
  let host = a, port = null
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

export function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRES = /^[A-Za-z0-9\-._~]$/

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRES.test(c) ? c : '%' + h.toUpperCase()
  })
}

function check(s, name) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(`the ${name} has a truncated percent-encoding`)
}

export function validate(r) {
  check(r.path, 'path')
  if (r.auth !== null) {
    const a = splitAuth(r.auth)
    if (a.userinfo !== null) check(a.userinfo, 'userinfo')
    check(a.host, 'host')
  }
  if (r.query !== null) check(r.query, 'query')
  if (r.fragment !== null) check(r.fragment, 'fragment')
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(r) {
  const scheme = r.scheme === null ? null : lower(r.scheme)
  let out = ''
  if (scheme !== null) out += scheme + ':'
  let path = pct(r.path)
  if (r.auth !== null) {
    const a = splitAuth(r.auth)
    let auth = ''
    if (a.userinfo !== null) auth += pct(a.userinfo) + '@'
    auth += lower(pct(a.host))
    if (a.port !== null && a.port !== '' && a.port !== DEFAULT_PORT[scheme]) auth += ':' + a.port
    out += '//' + auth
  }
  path = removeDots(path)
  if (r.auth !== null && path === '') path = '/'
  out += path
  if (r.query !== null) out += '?' + pct(r.query)
  if (r.fragment !== null) out += '#' + pct(r.fragment)
  return out
}

export function resolve(base, ref) {
  const t = { scheme: null, auth: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.auth !== null) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.auth = base.auth
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== null ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.auth !== null && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}
EOF
cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, validate, UriError } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
try {
  lines.forEach((line, i) => {
    const n = i + 1
    try {
      if (mode === 'normalize') {
        const r = parse(line)
        validate(r)
        out.push(normalize(r))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new UriError('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === null) throw new UriError('the base has no scheme')
        const t = resolve(base, parse(line.slice(sp + 1)))
        validate(t)
        out.push(normalize(t))
      }
    } catch (e) {
      if (e instanceof UriError) throw new UriError(`line ${n}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
EOF
