import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const advance = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const add = (kind, body, l, c) => tokens.push({ kind, body, line: l, col: c })

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') advance()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      advance(); advance()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '*' && cs[i + 1] === '/') { advance(); advance(); depth-- }
        else if (cs[i] === '/' && cs[i + 1] === '*') { advance(); advance(); depth++ }
        else advance()
      }
      continue
    }
    const sl = line, sc = col
    if (c === 'r' && cs[i + 1] === '"') {
      advance(); advance()
      let body = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = advance()
        if (d === '"') break
        body += d
      }
      add('rawstring', JSON.stringify(body), sl, sc)
      continue
    }
    if (isLetter(c) || c === '_') {
      let s = ''
      while (i < n && isIdent(cs[i])) s += advance()
      add(KEYWORDS.has(s) ? 'keyword' : 'ident', s, sl, sc)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const take = () => { s += advance() }
      const run = (isD) => {
        // digits with single underscores between digits; caller guarantees first is digit
        take()
        while (i < n) {
          if (isD(cs[i])) take()
          else if (cs[i] === '_' && isD(cs[i + 1])) { take(); take() }
          else break
        }
      }
      const p = (cs[i + 1] || '').toLowerCase()
      if (c === '0' && (p === 'x' || p === 'b' || p === 'o')) {
        const isD = p === 'x' ? isHex : p === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        take(); take()
        if (isD(cs[i])) run(isD)
        else bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) { take(); run(isDigit) }
          else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) { take(); take(); run(isDigit) }
