      }
      add('number', s, sl, sc)
      continue
    }
    if (c === '"') {
      advance()
      let body = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const bl = line, bc = col
        const d = advance()
        if (d === '"') break
        if (d === '\n') throw new ScanError(bl, bc, 'newline in string')
        if (d !== '\\') { body += d; continue }
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = advance()
        const invalid = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') body += '\n'
        else if (e === 't') body += '\t'
        else if (e === 'r') body += '\r'
        else if (e === '\\') body += '\\'
        else if (e === '"') body += '"'
        else if (e === '0') body += '\0'
        else if (e === 'x') {
          let h = ''
          for (let k = 0; k < 2; k++) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (!isHex(cs[i])) throw invalid()
            h += advance()
          }
          body += String.fromCharCode(parseInt(h, 16))
        } else if (e === 'u') {
          if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
          if (cs[i] !== '{') throw invalid()
          advance()
          let h = ''
          for (;;) {
            if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
            if (cs[i] === '}') break
            if (!isHex(cs[i])) throw invalid()
            h += advance()
          }
          advance()
          if (h === '' || parseInt(h, 16) > 0x10ffff) throw invalid()
          body += String.fromCodePoint(parseInt(h, 16))
        } else throw invalid()
      }
      add('string', JSON.stringify(body), sl, sc)
      continue
    }
    const two = c + (cs[i + 1] || '')
    if (PUNCT2.has(two)) { advance(); advance(); add('punct', two, sl, sc); continue }
    if (PUNCT1.has(c)) { advance(); add('punct', c, sl, sc); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (err) {
    if (!(err instanceof ScanError)) throw err
    process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
