        if (x.k === 'err') return x
        const y = toNum(r)
        if (y.k === 'err') return y
        switch (n.op) {
          case '+': return num(x.v + y.v)
          case '-': return num(x.v - y.v)
          case '*': return num(x.v * y.v)
          case '/': return y.v === 0 ? err('#DIV/0!') : num(x.v / y.v)
          default: return num(Math.pow(x.v, y.v))
        }
      }
    }
    return err('#ERR!')
  }

  const result = new Map()
  for (const c of cells) result.set(c.key, cellValue(c.key))
  return result
}
