      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { t: 'paren', e }
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            const a = cmp()
            if (a.t === 'range') a.direct = true
            args.push(a)
